@fg_group.command("derive")
@click.argument("name")
@click.option("--base", "base_fg", required=True, help="Base feature group name.")
@click.option(
    "--join",
    "joins",
    multiple=True,
    help='Join spec, repeatable: "<fg>[:<ver>] <INNER|LEFT|RIGHT|FULL> <on>[=<right_on>] [prefix]".',
)
@click.option(
    "--primary-key", "primary_key", required=True, help="Comma-separated primary keys."
)
@click.option(
    "--event-time", "event_time", help="Event-time column for the derived FG."
)
@click.option("--online", is_flag=True, help="Enable online store for the derived FG.")
@click.option("--description", default="", help="Free-form description.")
@click.pass_context
def fg_derive(
    ctx: click.Context,
    name: str,
    base_fg: str,
    joins: tuple[str, ...],
    primary_key: str,
    event_time: str | None,
    online: bool,
    description: str,

def fg_search(
    ctx: click.Context,
    name: str,
    vector: str,
    col: str | None,
    k: int,
    version: int | None,
) -> None:
    """Run a KNN similarity search against a feature group's embedding column.

    Args:
        ctx: Click context.
        name: Feature group name.
        vector: Comma-separated query vector.
        col: Embedding column; inferred when omitted.
        k: Number of neighbors to return.
        version: Feature group version.
    """
    fg = _get_fg(ctx, name, version)
    try:
        query = [float(x) for x in vector.split(",") if x.strip()]
    except ValueError as exc:
        raise click.BadParameter(
            f"Invalid vector: {exc}", param_hint="--vector"
        ) from exc

    try:
        results = fg.find_neighbors(embedding=query, col=col, k=k)
    except Exception as exc:  # noqa: BLE001
        raise click.ClickException(f"KNN search failed: {exc}") from exc

    if output.JSON_MODE:
        output.print_json(
            [{"score": score, "row": list(row)} for score, row in results or []]
        )
        return
    rows = [
        [f"{score:.4f}", ", ".join(str(v) for v in row)] for score, row in results or []
    ]
    output.print_table(["SCORE", "ROW"], rows)


@fg_group.command("keywords")
@click.argument("name")
@click.option("--version", type=int, help="Feature group version.")
@click.pass_context
def fg_keywords(ctx: click.Context, name: str, version: int | None) -> None:
    """Show all tags attached to a feature group (aka keywords).

    Args:
        ctx: Click context.
        name: Feature group name.
        version: Feature group version.
    """
    fg = _get_fg(ctx, name, version)
    try:
        tags = fg.get_tags()
    except Exception as exc:  # noqa: BLE001
        raise click.ClickException(f"Could not read tags: {exc}") from exc

    if output.JSON_MODE:
        output.print_json({k: _tag_value(v) for k, v in (tags or {}).items()})
        return
    rows = [[k, _tag_value(v)] for k, v in (tags or {}).items()]
    output.print_table(["KEYWORD", "VALUE"], rows)


@fg_group.command("add-keyword")
@click.argument("name")
@click.argument("keyword")
@click.option("--value", default="true", help="Tag value; defaults to 'true'.")
@click.option("--version", type=int, help="Feature group version.")
@click.pass_context
def fg_add_keyword(
    ctx: click.Context, name: str, keyword: str, value: str, version: int | None
) -> None:
    """Attach a keyword (tag) to a feature group.

    Args:
        ctx: Click context.
        name: Feature group name.
        keyword: Tag name.
        value: Tag value.
        version: Feature group version.
    """
    fg = _get_fg(ctx, name, version)
    try:
        fg.add_tag(name=keyword, value=value)
    except Exception as exc:  # noqa: BLE001
        raise click.ClickException(f"Could not add keyword: {exc}") from exc
    output.success("✓ Added keyword '%s' to %s", keyword, name)


@fg_group.command("remove-keyword")
@click.argument("name")

def _find_neighbors(
    self,
    embedding,
    feature: Feature = None,
    index_name=None,
    k=10,
    filter: Filter | Logic = None,
    options=None,
):
    if not feature:
        if not self._embedding_features:
            raise ValueError("embedding col is not defined.")
        if len(self._embedding_features) > 1:
            raise ValueError("More than 1 embedding columns but col is not defined")
        embedding_feature = list(self._embedding_features.values())[0]
    else:
        embedding_feature = self._embedding_features.get(feature, None)
        if embedding_feature is None:
            raise ValueError(
                f"feature: {feature.name} is not an embedding feature."
            )
    self._check_filter(filter, embedding_feature.feature_group)
    col_name = embedding_feature.embedding_index.col_prefix + embedding_feature.name
    query = {
        "size": k,
        "query": {
            "bool": {
                "must": [
                    {"knn": {col_name: {"vector": embedding, "k": k}}},
                    {"exists": {"field": col_name}},
                ]
                + self._get_query_filter(
                    filter, embedding_feature.embedding_index.col_prefix
                )
            }
        },
        "_source": list(
            self._fg_vdb_col_fg_col_map.get(
                embedding_feature.feature_group.id
            ).keys()
        ),
    }
    if not index_name:
        index_name = embedding_feature.embedding_index.index_name

    opensearch_client = OpenSearchClientSingleton(
        feature_store_id=embedding_feature.feature_group.feature_store_id
    )
    results = opensearch_client._search(
        body=query, index=index_name, options=options
    )

    # When using project index (`embedding_feature.embedding_index.col_prefix` is not empty), sometimes the total number of result returned is less than k. Possible reason is that when using project index, some embedding columns have null value if the row is from a different feature group. And opensearch filter out the result where embedding is null after retrieving the top k results. So search 3 times more data if it is using project index and size of result is not k.
    if (
        embedding_feature.embedding_index.col_prefix
        and len(results["hits"]["hits"]) != k
    ):
        # Get the max number of results allowed to request if it is not available.
        # This is expected to be executed once only.
        if not VectorDbClient._index_result_limit_k.get(index_name):
            query["query"]["bool"]["must"][0]["knn"][col_name]["k"] = 2**31 - 1
            try:
                # It is expected that this request ALWAYS fails because requested k is too large.
                # The purpose here is to get the max k allowed from the vector database, and cache it.
                opensearch_client._search(
                    body=query, index=index_name, options=options
                )
            except VectorDatabaseException as e:
                if (
                    e.reason == VectorDatabaseException.REQUESTED_K_TOO_LARGE
                    and e.info.get(
                        VectorDatabaseException.REQUESTED_K_TOO_LARGE_INFO_K
                    )
                ):
                    VectorDbClient._index_result_limit_k[index_name] = e.info.get(
                        VectorDatabaseException.REQUESTED_K_TOO_LARGE_INFO_K
                    )
                else:
                    raise e
        query["query"]["bool"]["must"][0]["knn"][col_name]["k"] = min(
            VectorDbClient._index_result_limit_k.get(index_name, k), 3 * k
        )
        results = opensearch_client._search(
            body=query, index=index_name, options=options
        )

    # https://opensearch.org/docs/latest/search-plugins/knn/approximate-knn/#spaces
    return [
        (
            1 / item["_score"] - 1,
            self._convert_to_pandas_type(
                embedding_feature.feature_group.columns,
                self._rewrite_result_key(
                    item["_source"],
                    self._fg_vdb_col_td_col_map[embedding_feature.feature_group.id],
                ),
            ),
        )
        for item in results["hits"]["hits"]
    ]
